115	impl IdeWorld for TestWorld {
116	    fn upcast(&self) -> &dyn World {
117	        self
118	    }
119	
120	    fn files(&self, base: FileId, prefix: Option<&str>) -> Vec<VirtualPath> {
121	        let dir = base.vpath().parent();
122	
123	        std::iter::once(self.main.id())
124	            .chain(self.files.sources.keys().copied())
125	            .chain(self.files.assets.keys().copied())
126	            .map(|id| id.vpath().clone())
127	            .filter(|path| {
128	                prefix.is_none_or(|prefix| {
129	                    dir.as_ref()
130	                        .map(|dir| path.relative_from(dir))
131	                        .is_none_or(|relative| relative.starts_with(prefix))
132	                })
133	            })
134	            .collect()
135	    }
136	
137	    fn packages(&self) -> &[(PackageSpec, Option<EcoString>)] {
138	        const LIST: &[(PackageSpec, Option<EcoString>)] = &[(
139	            PackageSpec {
140	                // NOTE: This literal, `"preview"`, should match the const, `DEFAULT_NAMESPACE`,
141	                // defined in `crates/typst-kit/src/package.rs`. However, we should always use the
142	                // literal here, not `DEFAULT_NAMESPACE`, so that this test fails if its value
143	                // changes in an unexpected way.
144	                namespace: EcoString::inline("preview"),
145	                name: EcoString::inline("example"),
146	                version: PackageVersion { major: 0, minor: 1, patch: 0 },
147	            },
148	            None,
149	        )];
150	        LIST
151	    }
152	}
