183	/// The extended standard library for testing.
184	fn library() -> Library {
185	    // Set page width to 120pt with 10pt margins, so that the inner page is
186	    // exactly 100pt wide. Page height is unbounded and font size is 10pt so
187	    // that it multiplies to nice round numbers.
188	    let mut lib = typst::Library::builder([
