230	/// Specifies a position in a file for a test. Negative numbers index from the
231	/// back. `-1` is at the very back.
232	pub trait FilePos {
233	    fn resolve(self, world: &TestWorld) -> (Source, usize);
234	}
235	
236	impl FilePos for isize {
237	    #[track_caller]
238	    fn resolve(self, world: &TestWorld) -> (Source, usize) {
239	        (world.main.clone(), cursor(&world.main, self))
240	    }
241	}
242	
243	impl FilePos for (&str, isize) {
244	    #[track_caller]
245	    fn resolve(self, world: &TestWorld) -> (Source, usize) {
246	        let id = RootedPath::new(VirtualRoot::Project, VirtualPath::new(self.0).unwrap())
247	            .intern();
248	        let source = world.source(id).unwrap();
249	        let cursor = cursor(&source, self.1);
250	        (source, cursor)
251	    }
252	}
