254	/// Resolve a signed index (negative from the back) to a unsigned index.
255	#[track_caller]
256	fn cursor(source: &Source, cursor: isize) -> usize {
257	    if cursor < 0 {
258	        source.text().len().checked_add_signed(cursor + 1).unwrap()
259	    } else {
260	        cursor as usize
261	    }
262	}
