27	/// Autocomplete a cursor position in a source file.
28	///
29	/// Returns the position from which the completions apply and a list of
30	/// completions.
31	///
32	/// When `explicit` is `true`, the user requested the completion by pressing
33	/// control and space or something similar.
34	///
35	/// Passing an `output` (from a previous compilation) is optional, but enhances
36	/// the autocompletions. Label completions, for instance, are only generated
37	/// when the document is available.
38	pub fn autocomplete(
39	    world: &dyn IdeWorld,
40	    output: Option<impl AsOutput>,
41	    source: &Source,
42	    cursor: usize,
43	    explicit: bool,
44	) -> Option<(usize, Vec<Completion>)> {
45	    let leaf = LinkedNode::new(source.root()).leaf_at(cursor, Side::Before)?;
46	    let mut ctx = CompletionContext::new(
47	        world,
48	        output.as_ref().map(|v| v.as_output()),
49	        source,
50	        &leaf,
51	        cursor,
52	        explicit,
53	    );
54	
55	    // Getting the syntax mode also ensures we are not in a comment.
56	    let mode = ctx.leaf.mode_after()?;
57	
58	    _ = complete_field_accesses(&mut ctx)
59	        || complete_open_labels(&mut ctx)
60	        || complete_imports(&mut ctx)
61	        || complete_rules(&mut ctx)
62	        || complete_params(&mut ctx)
63	        // Only attempt the general completions after the more specific ones.
64	        || match mode {
65	            SyntaxMode::Markup => complete_markup(&mut ctx),
66	            SyntaxMode::Math => complete_math(&mut ctx),
67	            SyntaxMode::Code => complete_code(&mut ctx),
68	        };
69	
70	    Some((ctx.from, ctx.completions))
71	}
