89	/// A kind of item that can be completed.
90	#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
91	#[serde(rename_all = "kebab-case")]
92	pub enum CompletionKind {
93	    /// A syntactical structure.
94	    Syntax,
95	    /// A function.
96	    Func,
97	    /// A type.
98	    Type,
99	    /// A function parameter.
100	    Param,
101	    /// A constant.
102	    Constant,
103	    /// A file path.
104	    Path,
105	    /// A package.
106	    Package,
107	    /// A label.
108	    Label,
109	    /// A font family.
110	    Font,
111	    /// A symbol.
