253	/// Complete half-finished labels.
254	fn complete_open_labels(ctx: &mut CompletionContext) -> bool {
255	    // A label anywhere in code: "(<la|".
256	    if ctx.leaf.kind().is_error() && ctx.leaf.leaf_text().starts_with('<') {
257	        ctx.from = ctx.leaf.offset() + 1;
258	        ctx.label_completions();
259	        return true;
260	    }
261	
262	    false
263	}
264	
265	/// Complete imports.
266	fn complete_imports(ctx: &mut CompletionContext) -> bool {
267	    // In an import path for a file or package:
268	    // "#import "|",
269	    if let Some(SyntaxKind::ModuleImport | SyntaxKind::ModuleInclude) =
270	        ctx.leaf.parent_kind()
271	        && let Some(ast::Expr::Str(str)) = ctx.leaf.cast()
272	    {
273	        let value = str.get();
274	        ctx.from = ctx.leaf.offset();
275	        if value.starts_with('@') {
276	            let all_versions = value.contains(':');
277	            ctx.package_completions(all_versions);
278	        } else {
279	            ctx.file_completions_with_extensions(&["typ"]);
280	        }
281	        return true;
282	    }
283	
284	    // Behind an import list:
285	    // "#import "path.typ": |",
286	    // "#import "path.typ": a, b, |".
287	    if let Some(prev) = ctx.leaf.prev_sibling()
288	        && let Some(ast::Expr::ModuleImport(import)) = prev.get().cast()
289	        && let Some(ast::Imports::Items(items)) = import.imports()
290	        && let Some(source) = prev.children().find(|child| child.is::<ast::Expr>())
291	    {
292	        ctx.from = ctx.cursor;
293	        import_item_completions(ctx, items, &source);
294	        return true;
295	    }
296	
297	    // Behind a half-started identifier in an import list:
298	    // "#import "path.typ": thi|",
299	    if ctx.leaf.kind() == SyntaxKind::Ident
300	        && let Some(parent) = ctx.leaf.parent()
301	        && parent.kind() == SyntaxKind::ImportItemPath
302	        && let Some(grand) = parent.parent()
303	        && grand.kind() == SyntaxKind::ImportItems
304	        && let Some(great) = grand.parent()
305	        && let Some(ast::Expr::ModuleImport(import)) = great.get().cast()
306	        && let Some(ast::Imports::Items(items)) = import.imports()
307	        && let Some(source) = great.children().find(|child| child.is::<ast::Expr>())
308	    {
309	        ctx.from = ctx.leaf.offset();
310	        import_item_completions(ctx, items, &source);
311	        return true;
312	    }
313	
314	    false
315	}
