317	/// Add completions for all exports of a module.
318	fn import_item_completions<'a>(
319	    ctx: &mut CompletionContext<'a>,
320	    existing: ast::ImportItems<'a>,
321	    source: &LinkedNode,
322	) {
323	    let Some(value) = analyze_import(ctx.world, source) else { return };
324	    let Some(scope) = value.scope() else { return };
325	
326	    if existing.iter().next().is_none() {
327	        ctx.snippet_completion("*", "*", "Import everything.");
328	    }
329	
330	    for (name, binding) in scope.iter() {
331	        if existing.iter().all(|item| item.original_name().as_str() != name)
332	            && let Ok(value) = binding.read(ctx.binding_guard())
333	        {
334	            ctx.value_completion(name.clone(), value);
335	        }
336	    }
337	}
