375	/// Add completions for all functions from the global scope.
376	fn set_rule_completions(ctx: &mut CompletionContext) {
377	    ctx.scope_completions(true, |value| {
378	        matches!(
379	            value,
380	            Value::Func(func) if func.params().any(|param| param.settable())
381	        )
382	    });
383	}
