385	/// Add completions for selectors.
386	fn show_rule_selector_completions(ctx: &mut CompletionContext) {
387	    ctx.scope_completions(
388	        false,
389	        |value| matches!(value, Value::Func(func) if func.to_element().is_some()),
390	    );
391	
392	    ctx.enrich("", ": ");
393	
394	    ctx.snippet_completion(
395	        "text selector",
396	        "\"${text}\": ${}",
397	        "Replace occurrences of specific text.",
398	    );
399	
400	    ctx.snippet_completion(
401	        "regex selector",
402	        "regex(\"${regex}\"): ${}",
403	        "Replace matches of a regular expression.",
404	    );
405	}
