502	/// Add completions for the parameters of a function.
503	fn param_completions<'a>(
504	    ctx: &mut CompletionContext<'a>,
505	    callee: &LinkedNode<'a>,
506	    set: bool,
507	    args: ast::Args<'a>,
508	    args_linked: &LinkedNode<'a>,
509	) {
510	    let Some(value) = analyze_expr_with_fallback(ctx.world, callee) else { return };
511	    let Ok(func) = value.cast::<Func>() else { return };
512	
513	    // Determine which arguments are already present.
514	    let mut existing_positional = 0;
515	    let mut existing_named = FxHashSet::default();
516	    for arg in args.items() {
517	        match arg {
518	            ast::Arg::Pos(_) => {
519	                let Some(node) = args_linked.find(arg.span()) else { continue };
520	                if node.range().end < ctx.cursor {
521	                    existing_positional += 1;
522	                }
523	            }
524	            ast::Arg::Named(named) => {
525	                existing_named.insert(named.name().as_str());
526	            }
527	            ast::Arg::Spread(_) => {}
528	        }
529	    }
530	
531	    let mut skipped_positional = 0;
532	    for param in func.params() {
533	        if set && !param.settable() {
534	            continue;
535	        }
536	
537	        if param.positional() {
538	            if skipped_positional < existing_positional && !param.variadic() {
539	                skipped_positional += 1;
540	                continue;
541	            }
542	
543	            param_value_completions(ctx, &func, &param);
544	        }
545	
546	        if let Some(name) = param.name()
547	            && param.named()
548	        {
549	            if existing_named.contains(name) {
550	                continue;
551	            }
552	
553	            let apply = if param.name() == Some("caption") {
554	                eco_format!("{name}: [${{}}]")
555	            } else {
556	                eco_format!("{name}: ${{}}")
557	            };
558	
559	            ctx.completions.push(Completion {
560	                kind: CompletionKind::Param,
561	                label: name.into(),
562	                apply: Some(apply),
563	                detail: find_param_docs(ctx.world, &param).map(|docs| docs.summary()),
564	            });
565	        }
566	    }
567	
568	    if ctx.before.ends_with(',') {
569	        ctx.enrich(" ", "");
570	    }
571	}
