227	/// Categorize an expression into common classes IDE functionality can operate
228	/// on.
229	pub fn deref_target(node: LinkedNode<'_>) -> Option<DerefTarget<'_>> {
230	    // Move to the first ancestor that is an expression.
231	    let mut ancestor = node;
232	    while !ancestor.is::<ast::Expr>() {
233	        ancestor = ancestor.parent()?.clone();
234	    }
235	
236	    // Identify convenient expression kinds.
237	    let expr_node = ancestor;
238	    let expr = expr_node.cast::<ast::Expr>()?;
239	    Some(match expr {
240	        ast::Expr::Label(_) => DerefTarget::Label(expr_node),
241	        ast::Expr::Ref(_) => DerefTarget::Ref(expr_node),
242	        // TODO: Add MathCall?
243	        ast::Expr::FuncCall(call) => {
244	            DerefTarget::Callee(expr_node.find(call.callee().span())?)
245	        }
246	        ast::Expr::SetRule(set) => {
247	            DerefTarget::Callee(expr_node.find(set.target().span())?)
248	        }
249	        ast::Expr::Ident(_)
250	        | ast::Expr::FieldAccess(_)
251	        | ast::Expr::MathIdent(_)
252	        | ast::Expr::MathFieldAccess(_) => DerefTarget::VarAccess(expr_node),
253	        ast::Expr::Str(_) => {
254	            let parent = expr_node.parent()?;
255	            if parent.kind() == SyntaxKind::ModuleImport {
256	                DerefTarget::ImportPath(expr_node)
257	            } else if parent.kind() == SyntaxKind::ModuleInclude {
258	                DerefTarget::IncludePath(expr_node)
259	            } else {
260	                DerefTarget::Code(expr_node)
261	            }
262	        }
263	        _ if expr.hash()
264	            || matches!(expr_node.kind(), SyntaxKind::MathIdent | SyntaxKind::Error) =>
265	        {
266	            DerefTarget::Code(expr_node)
267	        }
268	        _ => return None,
269	    })
270	}
