115	/// Complete field accesses.
116	fn complete_field_accesses(ctx: &mut CompletionContext) -> bool {
117	    let (after_dot, textual_dot) = match ctx.leaf.kind() {
118	        SyntaxKind::Dot => (true, false),
119	        SyntaxKind::Text | SyntaxKind::MathSymbol if ctx.leaf.leaf_text() == "." => {
120	            (true, true)
121	        }
122	        _ => (false, false),
123	    };
124	
125	    // After an expression plus a dot: "emoji.|".
126	    if after_dot
127	        && let Some(prev) = ctx.leaf.prev_sibling()
128	        // We don't complete when we had trivia between the previous node
129	        // and a textual dot: `[#x .|]` or `$arrow .|$`
130	        && (!textual_dot || prev.range().end == ctx.leaf.range().start)
131	        && prev.is::<ast::Expr>() // The dot must comes after an expression.
132	        // And that expression must allow field access
133	        && (prev.parent_kind() != Some(SyntaxKind::Markup)
134	            || prev.prev_sibling_kind() == Some(SyntaxKind::Hash))
135	        && let Some((value, styles)) = analyze_expr(ctx.world, &prev).into_iter().next()
136	    {
137	        ctx.from = ctx.cursor;
138	        field_access_completions(ctx, &value, &styles);
139	        return true;
140	    }
141	
142	    // After a started field access: "emoji.fa|".
143	    if matches!(ctx.leaf.kind(), SyntaxKind::Ident | SyntaxKind::MathIdent)
144	        && let Some(prev) = ctx.leaf.prev_sibling()
145	        && prev.kind() == SyntaxKind::Dot
146	        && let Some(prev_prev) = prev.prev_sibling()
147	        && prev_prev.is::<ast::Expr>()
148	        && let Some((value, styles)) =
149	            analyze_expr(ctx.world, &prev_prev).into_iter().next()
150	    {
151	        debug_assert!(matches!(
152	            ctx.leaf.parent_kind(),
153	            Some(SyntaxKind::FieldAccess | SyntaxKind::MathFieldAccess),
154	        ));
155	        ctx.from = ctx.leaf.offset();
156	        field_access_completions(ctx, &value, &styles);
157	        return true;
158	    }
159	
160	    false
161	}
