163	/// Add completions for all fields on a value.
164	fn field_access_completions(
165	    ctx: &mut CompletionContext,
166	    value: &Value,
167	    styles: &Option<Styles>,
168	) {
169	    let scopes = {
170	        let ty = value.ty().scope();
171	        let elem = match value {
172	            Value::Content(content) => Some(content.elem().scope()),
173	            _ => None,
174	        };
175	        elem.into_iter().chain(Some(ty))
176	    };
177	
178	    // Autocomplete methods from the element's or type's scope. We only complete
179	    // those which have a `self` parameter.
180	    for (name, binding) in scopes.flat_map(|scope| scope.iter()) {
181	        if let Ok(value) = binding.read(ctx.binding_guard())
182	            && let Ok(func) = value.clone().cast::<Func>()
183	            && let Some(param) = func.params().next()
184	            && param.name() == Some("self")
185	        {
186	            ctx.call_completion(name.clone(), value);
187	        }
188	    }
189	
190	    if let Some(scope) = value.scope() {
191	        for (name, binding) in scope.iter() {
192	            if let Ok(value) = binding.read(ctx.binding_guard()) {
193	                ctx.call_completion(name.clone(), value);
194	            }
195	        }
196	    }
197	
198	    for &field in fields_on(value.ty()) {
199	        // Complete the field name along with its value. Notes:
200	        // 1. No parentheses since function fields cannot currently be called
201	        // with method syntax;
202	        // 2. We can unwrap the field's value since it's a field belonging to
203	        // this value's type, so accessing it should not fail.
204	        if let Ok(value) = value.field(field, ctx.binding_guard()) {
205	            ctx.value_completion(field, &value);
206	        }
207	    }
208	
209	    match value {
210	        Value::Symbol(symbol) => {
211	            for modifier in symbol.modifiers() {
212	                if let Ok(modified) = symbol.clone().modified((), modifier) {
213	                    ctx.completions.push(Completion {
214	                        kind: CompletionKind::Symbol(modified.get().into()),
215	                        label: modifier.into(),
216	                        apply: None,
217	                        detail: None,
218	                    });
219	                }
220	            }
221	        }
222	        Value::Content(content) => {
223	            for (name, value) in content.fields() {
224	                ctx.value_completion(name, &value);
225	            }
226	        }
227	        Value::Dict(dict) => {
228	            for (name, value) in dict {
229	                ctx.value_completion(name.clone(), value);
230	            }
231	        }
232	        Value::Args(args) => {
233	            for (name, value) in &args.to_named() {
234	                ctx.value_completion(name.clone(), value);
235	            }
236	        }
237	        Value::Func(func) => {
238	            // Autocomplete get rules.
239	            if let Some((elem, styles)) = func.to_element().zip(styles.as_ref()) {
240	                for param in elem.params() {
241	                    if let Some(field_accessor) = elem.settable_field_accessor(param.name)
242	                    {
243	                        let value = field_accessor(StyleChain::new(styles));
244	                        ctx.value_completion(param.name, &value);
245	                    }
246	                }
247	            }
248	        }
249	        _ => {}
250	    }
251	}
