339	/// Complete set and show rules.
340	fn complete_rules(ctx: &mut CompletionContext) -> bool {
341	    // We don't want to complete directly behind the keyword.
342	    if !ctx.leaf.kind().is_trivia() {
343	        return false;
344	    }
345	
346	    let Some(prev) = ctx.leaf.prev_leaf() else { return false };
347	
348	    // Behind the set keyword: "set |".
349	    if matches!(prev.kind(), SyntaxKind::Set) {
350	        ctx.from = ctx.cursor;
351	        set_rule_completions(ctx);
352	        return true;
353	    }
354	
355	    // Behind the show keyword: "show |".
356	    if matches!(prev.kind(), SyntaxKind::Show) {
357	        ctx.from = ctx.cursor;
358	        show_rule_selector_completions(ctx);
359	        return true;
360	    }
361	
362	    // Behind a half-completed show rule: "show strong: |".
363	    if let Some(prev) = ctx.leaf.prev_leaf()
364	        && matches!(prev.kind(), SyntaxKind::Colon)
365	        && matches!(prev.parent_kind(), Some(SyntaxKind::ShowRule))
366	    {
367	        ctx.from = ctx.cursor;
368	        show_rule_recipe_completions(ctx);
369	        return true;
370	    }
371	
372	    false
373	}
