430	/// Complete call and set rule parameters.
431	///
432	/// FUTURE: Make this work for math functions. This will require a much deeper
433	/// refactoring of `param_completions` below, including handling 2d arguments
434	/// correctly and ensuring we add a hash in math when suggesting to insert
435	/// values that aren't strings.
436	fn complete_params(ctx: &mut CompletionContext) -> bool {
437	    // Ensure that we are in a function call or set rule's argument list.
438	    let (callee, set, args, args_linked) = if let Some(parent) = ctx.leaf.parent()
439	        && let Some(parent) = match parent.kind() {
440	            SyntaxKind::Named => parent.parent(),
441	            _ => Some(parent),
442	        }
443	        && let Some(args) = parent.get().cast::<ast::Args>()
444	        && let Some(grand) = parent.parent()
445	        && let Some(expr) = grand.get().cast::<ast::Expr>()
446	        && let set = matches!(expr, ast::Expr::SetRule(_))
447	        && let Some(callee) = match expr {
448	            ast::Expr::FuncCall(call) => Some(call.callee()),
449	            ast::Expr::SetRule(set) => Some(set.target()),
450	            _ => None,
451	        }
452	        && let Some(callee) = grand.find(callee.span())
453	    {
454	        (callee, set, args, parent)
455	    } else {
456	        return false;
457	    };
458	
459	    // Find the piece of syntax that decides what we're completing.
460	    let mut deciding = ctx.leaf.clone();
461	    while !matches!(
462	        deciding.kind(),
463	        SyntaxKind::LeftParen
464	            | SyntaxKind::RightParen
465	            | SyntaxKind::Comma
466	            | SyntaxKind::Colon
467	    ) {
468	        let Some(prev) = deciding.prev_leaf() else { break };
469	        deciding = prev;
470	    }
471	
472	    // Parameter values: "func(param:|)", "func(param: |)".
473	    if let SyntaxKind::Colon = deciding.kind()
474	        && let Some(prev) = deciding.prev_leaf()
475	        && let Some(param) = prev.get().cast::<ast::Ident>()
476	    {
477	        if let Some(next) = deciding.next_leaf() {
478	            ctx.from = ctx.cursor.min(next.offset());
479	        }
480	
481	        named_param_value_completions(ctx, &callee, &param);
482	        return true;
483	    }
484	
485	    // Parameters: "func(|)", "func(hi|)", "func(12, |)", "func(12,|)" [explicit mode only]
486	    if let SyntaxKind::LeftParen | SyntaxKind::Comma = deciding.kind()
487	        && (deciding.kind() != SyntaxKind::Comma
488	            || deciding.range().end < ctx.cursor
489	            || ctx.explicit)
490	    {
491	        if let Some(next) = deciding.next_leaf() {
492	            ctx.from = ctx.cursor.min(next.offset());
493	        }
494	
495	        param_completions(ctx, &callee, set, args, args_linked);
496	        return true;
497	    }
498	
499	    false
500	}
