573	/// Add completions for the values of a named function parameter.
574	fn named_param_value_completions(
575	    ctx: &mut CompletionContext,
576	    callee: &LinkedNode,
577	    name: &str,
578	) {
579	    let Some(value) = analyze_expr_with_fallback(ctx.world, callee) else { return };
580	    let Ok(func) = value.cast::<Func>() else { return };
581	
582	    let Some(param) = func.param(name) else { return };
583	    if !param.named() {
584	        return;
585	    }
586	
587	    param_value_completions(ctx, &func, &param);
588	
589	    if ctx.before.ends_with(':') {
