633	/// Complete in markup mode.
634	fn complete_markup(ctx: &mut CompletionContext) -> bool {
635	    debug_assert_eq!(ctx.leaf.mode_after(), Some(SyntaxMode::Markup));
636	
637	    // Start of a reference: "@|".
638	    if ctx.leaf.kind() == SyntaxKind::Text && ctx.before.ends_with("@") {
639	        ctx.from = ctx.cursor;
640	        ctx.label_completions();
641	        return true;
642	    }
643	
644	    // An existing reference: "@he|".
645	    if ctx.leaf.kind() == SyntaxKind::RefMarker {
646	        ctx.from = ctx.leaf.offset() + 1;
647	        ctx.label_completions();
648	        return true;
649	    }
650	
651	    // Behind a half-completed binding: "#let x = |".
652	    if let Some(prev) = ctx.leaf.prev_leaf()
653	        && prev.kind() == SyntaxKind::Eq
654	        && prev.parent_kind() == Some(SyntaxKind::LetBinding)
655	    {
656	        ctx.from = ctx.cursor;
657	        code_completions(ctx, false);
658	        return true;
659	    }
660	
661	    // Behind a half-completed context block: "#context |".
662	    if let Some(prev) = ctx.leaf.prev_leaf()
663	        && prev.kind() == SyntaxKind::Context
664	    {
665	        ctx.from = ctx.cursor;
666	        code_completions(ctx, false);
667	        return true;
668	    }
669	
670	    // Directly after a raw block.
671	    let mut s = Scanner::new(ctx.text);
672	    s.jump(ctx.leaf.offset());
673	    if s.eat_if("```") {
674	        s.eat_while('`');
675	        let start = s.cursor();
676	        if s.eat_if(is_id_start) {
677	            s.eat_while(is_id_continue);
678	        }
679	        if s.cursor() == ctx.cursor {
680	            ctx.from = start;
681	            ctx.raw_completions();
682	        }
683	        return true;
684	    }
685	
686	    // Anywhere: "|".
687	    if ctx.explicit {
688	        ctx.from = ctx.cursor;
689	        markup_completions(ctx);
690	        return true;
691	    }
692	
693	    false
694	}
