8	/// Find the named items starting from the given position.
9	pub fn named_items<T>(
10	    world: &dyn IdeWorld,
11	    position: LinkedNode,
12	    mut recv: impl FnMut(NamedItem) -> Option<T>,
13	) -> Option<T> {
14	    let mut ancestor = Some(position);
15	    while let Some(node) = &ancestor {
16	        let mut sibling = Some(node.clone());
17	        while let Some(node) = &sibling {
18	            if let Some(v) = node.cast::<ast::LetBinding>() {
19	                let kind = if matches!(v.kind(), ast::LetBindingKind::Closure(..)) {
20	                    NamedItem::Fn
21	                } else {
22	                    NamedItem::Var
23	                };
24	                for ident in v.kind().bindings() {
25	                    if let Some(res) = recv(kind(ident)) {
26	                        return Some(res);
27	                    }
28	                }
29	            }
30	
31	            if let Some(v) = node.cast::<ast::ModuleImport>() {
32	                let imports = v.imports();
33	                let source = v.source();
34	
35	                let source_value = node
36	                    .find(source.span())
37	                    .and_then(|source| analyze_import(world, &source));
38	                let source_value = source_value.as_ref();
39	
40	                let module = source_value.and_then(|value| match value {
41	                    Value::Module(module) => Some(module),
42	                    _ => None,
43	                });
44	
45	                let name_and_span = match (imports, v.new_name()) {
46	                    // ```plain
47	                    // import "foo" as name
48	                    // import "foo" as name: ..
49	                    // ```
50	                    (_, Some(name)) => Some((name.get().clone(), name.span())),
51	                    // ```plain
52	                    // import "foo"
53	                    // ```
54	                    (None, None) => v.bare_name().ok().map(|name| (name, source.span())),
55	                    // ```plain
56	                    // import "foo": ..
57	                    // ```
58	                    (Some(..), None) => None,
59	                };
60	
61	                // Seeing the module itself.
62	                if let Some((name, span)) = name_and_span
63	                    && let Some(res) = recv(NamedItem::Module(&name, span, module))
64	                {
65	                    return Some(res);
66	                }
67	
68	                // Seeing the imported items.
69	                match imports {
70	                    // ```plain
71	                    // import "foo";
72	                    // ```
73	                    None => {}
74	                    // ```plain
75	                    // import "foo": *;
76	                    // ```
77	                    Some(ast::Imports::Wildcard) => {
78	                        if let Some(scope) = source_value.and_then(Value::scope) {
79	                            for (name, binding) in scope.iter() {
80	                                let Ok(value) =
81	                                    binding.read(world.silent_binding_guard())
82	                                else {
83	                                    continue;
84	                                };
85	
86	                                let item =
87	                                    NamedItem::Import(name, binding.span(), Some(value));
88	                                if let Some(res) = recv(item) {
89	                                    return Some(res);
90	                                }
91	                            }
92	                        }
93	                    }
94	                    // ```plain
95	                    // import "foo": items;
96	                    // ```
97	                    Some(ast::Imports::Items(items)) => {
98	                        for item in items.iter() {
99	                            let mut iter = item.path().iter();
100	                            let mut binding = source_value
101	                                .and_then(Value::scope)
102	                                .zip(iter.next())
103	                                .and_then(|(scope, first)| scope.get(&first));
104	
105	                            for ident in iter {
106	                                binding = binding.and_then(|binding| {
107	                                    binding
108	                                        .read(world.silent_binding_guard())
109	                                        .ok()?
110	                                        .scope()?
111	                                        .get(&ident)
112	                                });
113	                            }
114	
115	                            let bound = item.bound_name();
116	                            let (span, value) = match binding {
117	                                Some(binding) => (
118	                                    binding.span(),
119	                                    binding.read(world.silent_binding_guard()).ok(),
120	                                ),
121	                                None => (bound.span(), None),
122	                            };
123	
124	                            let item = NamedItem::Import(bound.get(), span, value);
125	                            if let Some(res) = recv(item) {
126	                                return Some(res);
127	                            }
128	                        }
129	                    }
130	                }
131	            }
132	
133	            sibling = node.prev_sibling();
134	        }
135	
136	        if let Some(parent) = node.parent() {
137	            if let Some(v) = parent.cast::<ast::ForLoop>()
138	                && node.prev_sibling_kind() != Some(SyntaxKind::In)
139	            {
140	                let pattern = v.pattern();
141	                for ident in pattern.bindings() {
142	                    if let Some(res) = recv(NamedItem::Var(ident)) {
143	                        return Some(res);
144	                    }
145	                }
146	            }
147	
148	            if let Some(v) = parent.cast::<ast::Closure>().filter(|v| {
149	                // Check if the node is in the body of the closure.
150	                let body = parent.find(v.body().span());
151	                body.is_some_and(|n| n.find(node.span()).is_some())
152	            }) {
153	                for param in v.params().children() {
154	                    match param {
155	                        ast::Param::Pos(pattern) => {
156	                            for ident in pattern.bindings() {
157	                                if let Some(t) = recv(NamedItem::Var(ident)) {
158	                                    return Some(t);
159	                                }
160	                            }
161	                        }
162	                        ast::Param::Named(n) => {
163	                            if let Some(t) = recv(NamedItem::Var(n.name())) {
164	                                return Some(t);
165	                            }
166	                        }
167	                        ast::Param::Spread(s) => {
168	                            if let Some(sink_ident) = s.sink_ident()
169	                                && let Some(t) = recv(NamedItem::Var(sink_ident))
170	                            {
171	                                return Some(t);
172	                            }
173	                        }
174	                    }
175	                }
176	            }
177	
178	            ancestor = Some(parent.clone());
179	            continue;
180	        }
181	
182	        break;
183	    }
184	
185	    None
186	}
