188	/// An item that is named.
189	pub enum NamedItem<'a> {
190	    /// A variable item.
191	    Var(ast::Ident<'a>),
192	    /// A function item.
193	    Fn(ast::Ident<'a>),
194	    /// A (imported) module.
195	    Module(&'a EcoString, Span, Option<&'a Module>),
196	    /// An imported item.
197	    Import(&'a EcoString, Span, Option<&'a Value>),
198	}
199	
200	impl<'a> NamedItem<'a> {
201	    pub(crate) fn name(&self) -> &'a EcoString {
202	        match self {
203	            NamedItem::Var(ident) => ident.get(),
204	            NamedItem::Fn(ident) => ident.get(),
205	            NamedItem::Module(name, _, _) => name,
206	            NamedItem::Import(name, _, _) => name,
207	        }
208	    }
209	
210	    pub(crate) fn value(&self) -> Option<Value> {
211	        match self {
212	            NamedItem::Var(..) | NamedItem::Fn(..) => None,
213	            NamedItem::Module(_, _, value) => value.cloned().map(Value::Module),
214	            NamedItem::Import(_, _, value) => value.cloned(),
215	        }
216	    }
217	
218	    pub(crate) fn span(&self) -> Span {
219	        match *self {
220	            NamedItem::Var(name) | NamedItem::Fn(name) => name.span(),
221	            NamedItem::Module(_, span, _) => span,
222	            NamedItem::Import(_, span, _) => span,
223	        }
224	    }
225	}
