796	/// Complete in math mode.
797	fn complete_math(ctx: &mut CompletionContext) -> bool {
798	    debug_assert_eq!(ctx.leaf.mode_after(), Some(SyntaxMode::Math));
799	
800	    // Behind existing atom or identifier: "$a|$" or "$abc|$".
801	    if matches!(ctx.leaf.kind(), SyntaxKind::MathLetter | SyntaxKind::MathIdent) {
802	        ctx.from = ctx.leaf.offset();
803	        math_completions(ctx);
804	        return true;
805	    }
806	
807	    // Anywhere: "$|$".
808	    if ctx.explicit {
809	        ctx.from = ctx.cursor;
810	        math_completions(ctx);
811	        return true;
812	    }
813	
814	    false
815	}
