841	/// Complete in code mode.
842	fn complete_code(ctx: &mut CompletionContext) -> bool {
843	    debug_assert_eq!(ctx.leaf.mode_after(), Some(SyntaxMode::Code));
844	
845	    // Start of embedded code in markup or math: "[#|]", "$#|$".
846	    // (if not in markup or math, the kind would be an `Error`).
847	    if ctx.leaf.kind() == SyntaxKind::Hash {
848	        ctx.from = ctx.cursor;
849	        code_completions(ctx, true);
850	        return true;
851	    }
852	
853	    // An existing identifier: "{ pa| }".
854	    // Ignores named pair keys as they are not variables (as in "(pa|: 23)").
855	    if ctx.leaf.kind() == SyntaxKind::Ident
856	        && (ctx.leaf.index() > 0 || ctx.leaf.parent_kind() != Some(SyntaxKind::Named))
857	    {
858	        ctx.from = ctx.leaf.offset();
859	        code_completions(ctx, false);
860	        return true;
861	    }
862	
863	    // Anywhere: "{ | }", "(|)", "(1,|)", "(a:|)".
864	    // But not within or after an expression, and also not part of a dictionary
865	    // key (as in "(pa: |,)")
866	    if ctx.explicit
867	        && ctx.leaf.parent_kind() != Some(SyntaxKind::Dict)
868	        && (ctx.leaf.kind().is_trivia()
869	            || matches!(
870	                ctx.leaf.kind(),
871	                SyntaxKind::LeftParen
872	                    | SyntaxKind::LeftBrace
873	                    | SyntaxKind::Comma
874	                    | SyntaxKind::Colon
875	            ))
876	    {
877	        ctx.from = ctx.cursor;
878	        code_completions(ctx, false);
879	        return true;
880	    }
881	
882	    false
883	}
