1042	/// See if the AST node is somewhere within a show rule applying to equations
1043	fn is_in_equation_show_rule(leaf: &LinkedNode<'_>) -> bool {
1044	    let mut node = leaf;
1045	    while let Some(parent) = node.parent() {
1046	        if let Some(expr) = parent.get().cast::<ast::Expr>()
1047	            && let ast::Expr::ShowRule(show) = expr
1048	            && let Some(ast::Expr::FieldAccess(field)) = show.selector()
1049	            && field.field().as_str() == "equation"
1050	        {
1051	            return true;
1052	        }
1053	        node = parent;
1054	    }
1055	    false
1056	}
