1058	/// Context for autocompletion.
1059	struct CompletionContext<'a> {
1060	    world: &'a (dyn IdeWorld + 'a),
1061	    output: Option<&'a dyn Output>,
1062	    text: &'a str,
1063	    before: &'a str,
1064	    after: &'a str,
1065	    leaf: &'a LinkedNode<'a>,
1066	    cursor: usize,
1067	    explicit: bool,
1068	    from: usize,
1069	    completions: Vec<Completion>,
1070	    seen_casts: FxHashSet<u128>,
1071	}
