1073	impl<'a> CompletionContext<'a> {
1074	    /// Create a new autocompletion context.
1075	    fn new(
1076	        world: &'a (dyn IdeWorld + 'a),
1077	        output: Option<&'a dyn Output>,
1078	        source: &'a Source,
1079	        leaf: &'a LinkedNode<'a>,
1080	        cursor: usize,
1081	        explicit: bool,
1082	    ) -> Self {
1083	        let text = source.text();
1084	        Self {
1085	            world,
1086	            output,
1087	            text,
1088	            before: &text[..cursor],
1089	            after: &text[cursor..],
1090	            leaf,
1091	            cursor,
1092	            explicit,
1093	            from: cursor,
1094	            completions: vec![],
1095	            seen_casts: FxHashSet::default(),
1096	        }
1097	    }
