1104	    /// Add a prefix and suffix to all applications.
1105	    fn enrich(&mut self, prefix: &str, suffix: &str) {
1106	        for Completion { label, apply, .. } in &mut self.completions {
1107	            let current = apply.as_ref().unwrap_or(label);
1108	            *apply = Some(eco_format!("{prefix}{current}{suffix}"));
1109	        }
1110	    }
