1117	        docs: &'static str,
1118	    ) {
1119	        self.completions.push(Completion {
1120	            kind: CompletionKind::Syntax,
1121	            label: label.into(),
1122	            apply: Some(snippet.into()),
1123	            detail: Some(docs.into()),
1124	        });
1125	    }
