1127	    /// Add completions for all font families.
1128	    fn font_completions(&mut self) {
1129	        let book = self.world.book();
1130	        let equation = is_in_equation_show_rule(self.leaf);
1131	        for (family, iter) in book.families() {
1132	            let variants: Vec<_> = iter.filter_map(|id| book.info(id)).collect();
1133	            let is_math = variants.iter().any(|f| f.flags.contains(FontFlags::MATH));
1134	            let detail = summarize_font_family(variants);
1135	            if !equation || is_math {
1136	                self.str_completion(
1137	                    family,
1138	                    Some(CompletionKind::Font),
