1145	    /// Add completions for all available packages.
1146	    fn package_completions(&mut self, all_versions: bool) {
1147	        let mut packages: Vec<_> = self.world.packages().iter().collect();
1148	        packages.sort_by_key(|(spec, _)| {
1149	            (&spec.namespace, &spec.name, Reverse(spec.version))
1150	        });
1151	        if !all_versions {
1152	            packages.dedup_by_key(|(spec, _)| (&spec.namespace, &spec.name));
1153	        }
1154	        for (package, description) in packages {
1155	            self.str_completion(
1156	                eco_format!("{package}"),
1157	                Some(CompletionKind::Package),
1158	                description.as_deref(),
1159	            );
1160	        }
1161	    }
