1163	    /// Add completions for all available files.
1164	    fn file_completions(&mut self, mut filter: impl FnMut(&VirtualPath) -> bool) {
1165	        let Some(current_id) = self.leaf.span().id() else { return };
1166	        let Some(current_dir) = current_id.vpath().parent() else { return };
1167	
1168	        let prefix =
1169	            Some(self.before[self.from..].trim_matches('\"')).filter(|s| !s.is_empty());
1170	
1171	        let mut paths: Vec<EcoString> = self
1172	            .world
1173	            .files(current_id, prefix)
1174	            .iter()
1175	            .filter(|&path| path != current_id.vpath() && filter(path))
1176	            .map(|path| path.relative_from(&current_dir))
1177	            .collect();
1178	
1179	        paths.sort();
1180	
1181	        for path in paths {
1182	            self.str_completion(path, Some(CompletionKind::Path), None);
1183	        }
1184	    }
