1186	    /// Add completions for all files with any of the given extensions.
1187	    ///
1188	    /// If the array is empty, all extensions are allowed.
1189	    fn file_completions_with_extensions(&mut self, extensions: &[&str]) {
1190	        if extensions.is_empty() {
1191	            self.file_completions(|_| true);
1192	        }
1193	        self.file_completions(|path| {
1194	            let ext = path
1195	                .extension()
1196	                .map(EcoString::from)
1197	                .unwrap_or_default()
1198	                .to_lowercase();
1199	            extensions.contains(&ext.as_str())
1200	        });
1201	    }
