1204	    fn raw_completions(&mut self) {
1205	        for (name, mut tags) in RawElem::languages() {
1206	            let lower = name.to_lowercase();
1207	            if !tags.contains(&lower.as_str()) {
1208	                tags.push(lower.as_str());
1209	            }
1210	
1211	            tags.retain(|tag| is_ident(tag));
1212	            if tags.is_empty() {
