1225	    /// Add completions for labels and references.
1226	    fn label_completions(&mut self) {
1227	        let Some(output) = self.output else { return };
1228	        let (labels, split) = analyze_labels(output);
1229	
1230	        let head = &self.text[..self.from];
1231	        let at = head.ends_with('@');
1232	        let open = !at && !head.ends_with('<');
1233	        let close = !at && !self.after.starts_with('>');
1234	        let citation = !at && self.before_window(15).contains("cite");
1235	
1236	        let (skip, take) = if at {
1237	            (0, usize::MAX)
1238	        } else if citation {
1239	            (split, usize::MAX)
1240	        } else {
1241	            (0, split)
1242	        };
1243	
1244	        for (label, detail) in labels.into_iter().skip(skip).take(take) {
1245	            self.completions.push(Completion {
1246	                kind: CompletionKind::Label,
1247	                apply: (open || close).then(|| {
