1482	/// What kind of parentheses to autocomplete for a function.
1483	enum BracketMode {
1484	    /// Round parenthesis, with the cursor within: `(|)`.
1485	    RoundWithin,
1486	    /// Round parenthesis, with the cursor after them: `()|`.
1487	    RoundAfter,
1488	    /// Round parenthesis, with newlines and indent.
1489	    RoundNewline,
1490	    /// Square brackets, with the cursor within: `[|]`.
1491	    SquareWithin,
1492	}
1493	
1494	impl BracketMode {
1495	    fn of(func: &Func) -> Self {
1496	        // If we have no parameters or only the self one, it's friendlier to put
1497	        // the cursor after the method call.
1498	        if func.params().all(|param| param.name() == Some("self")) {
1499	            return Self::RoundAfter;
1500	        }
1501	
1502	        match func.name() {
1503	            Some(
1504	                "emph" | "footnote" | "quote" | "strong" | "highlight" | "overline"
1505	                | "underline" | "smallcaps" | "strike" | "sub" | "super",
1506	            ) => Self::SquareWithin,
1507	            Some("colbreak" | "parbreak" | "linebreak" | "pagebreak") => Self::RoundAfter,
1508	            Some("figure" | "table" | "grid" | "stack") => Self::RoundNewline,
1509	            _ => Self::RoundWithin,
1510	        }
1511	    }
1512	}
