    /// Test dict field autocompletion in code and math.
    #[test]
    fn test_autocomplete_dict_fields() {
        let with = |text| &*format!("#let dict = (a: (c: 1), b: 2); {text}").leak();
        test(with("#dict."), -1)
            .must_include(["a", "b", "keys"])
            .must_exclude(["c"]);
        test(with("$dict.$"), -2)
            .must_include(["a", "b", "keys"])
            .must_exclude(["c"]);
        test(with("#dict.b."), -1)
            .must_include(["bit-or"])
            .must_exclude(["c"]);
        test(with("$dict.b.$"), -2)
            .must_include(["bit-or"])
            .must_exclude(["c"]);
        test(with("#dict.a."), -1)
            .must_include(["c", "keys"])
            .must_exclude(["b"]);
        test(with("$dict.a.$"), -2)
            .must_include(["c", "keys"])
            .must_exclude(["b"]);
        test(with("#dict.a.c."), -1).must_include(["bit-or"]);
        test(with("$dict.a.c.$"), -2).must_include(["bit-or"]);
    }

