    fn test_autocomplete_argument_fields() {
        let with = |text| {
            &*format!("#let args = arguments(0, a: arguments(c: 1), b: 2); {text}").leak()
        };
        test(with("#args."), -1)
            .must_include(["a", "b", "pos", "named"])
            .must_exclude(["c"]);
        test(with("$args.$"), -2)
            .must_include(["a", "b", "pos", "named"])
            .must_exclude(["c"]);
        test(with("#args.b."), -1)
            .must_include(["bit-or"])
            .must_exclude(["c"]);
        test(with("$args.b.$"), -2)
            .must_include(["bit-or"])
            .must_exclude(["c"]);
        test(with("#args.at(0)."), -1).must_include(["bit-or"]);
        test(with("#args.a."), -1)
            .must_include(["c", "pos", "named"])
            .must_exclude(["b"]);
        test(with("$args.a.$"), -2)
            .must_include(["c", "pos", "named"])
            .must_exclude(["b"]);
        test(with("#args.a.c."), -1).must_include(["bit-or"]);
        test(with("$args.a.c.$"), -2).must_include(["bit-or"]);
    }

    /// Test that the `before_window` doesn't slice into invalid byte
    /// boundaries.
    #[test]
    fn test_autocomplete_before_window_char_boundary() {
        test("😀😀     #text(font: \"\")", -3);
    }

    /// Ensure that autocompletion for `#cite(|)` completes bibligraphy labels,
    /// but no other labels.
    #[test]
    fn test_autocomplete_cite_function() {
        // First compile a working file to get a document.
        let mut world =
            TestWorld::new("#bibliography(\"works.bib\") <bib>").with_asset("works.bib");
        let doc = typst::compile::<PagedDocument>(&world).output.ok();

        // Then, add the invalid `#cite` call. Had the document been invalid
        // initially, we would have no populated document to autocomplete with.
        let end = world.main.text().len();
        world.main.edit(end..end, " #cite()");

        test_with_doc(&world, -2, doc.as_ref(), true)
            .must_include(["netwok", "glacier-melt", "supplement"])
            .must_exclude(["bib"]);
    }

    #[test]
    fn test_autocomplete_ref_function() {
        test_with_addition("x<test>", " #ref(<)", -2).must_include(["test"]);
    }

    #[test]
    fn test_autocomplete_ref_shorthand() {
        test_with_addition("x<test>", " @", -1).must_include(["test"]);
    }

    #[test]
    fn test_autocomplete_ref_shorthand_with_partial_identifier() {
        test_with_addition("x<test>", " @te", -1).must_include(["test"]);
    }

    #[test]
    fn test_autocomplete_ref_identical_labels_returns_single_completion() {
        let result = test_with_addition("x<test> y<test>", " @t", -1);
        let completions = result.completions();
        let label_count =
            completions.iter().filter(|c| c.kind == CompletionKind::Label).count();
        assert_eq!(label_count, 1);
    }

    /// Test what kind of brackets we autocomplete for function calls depending
    /// on the function and existing parens.
    #[test]
    fn test_autocomplete_bracket_mode() {
        test("#", 1).at("list").must_apply_as("list(${})");
        test("#", 1).at("linebreak").must_apply_as("linebreak()${}");
        test("#", 1).at("strong").must_apply_as("strong[${}]");
        test("#", 1).at("footnote").must_apply_as("footnote[${}]");
        test("#", 1).at("figure").must_apply_as("figure(\n  ${}\n)");
        test("#", 1).at("table").must_apply_as("table(\n  ${}\n)");
        test("#()", 1).at("list").must_apply_as(None);
        test("#[]", 1).at("strong").must_apply_as(None);
        test("$$", 1).at("overline").must_apply_as("overline(${})");
    }

    /// Test that we only complete positional parameters if they aren't
    /// already present.
    #[test]
    fn test_autocomplete_positional_param() {
        // No string given yet.
        test("#numbering()", -2).must_include(["string", "integer"]);
        // String is already given.
        test("#numbering(\"foo\", )", -2)
            .must_include(["integer"])
            .must_exclude(["string"]);
        // Integer is already given, but numbering is variadic.
        test("#numbering(\"foo\", 1, )", -2)
            .must_include(["integer"])
            .must_exclude(["string"]);
        // After argument list no completions.
        test("#numbering()", -1).must_exclude(["string"]);
    }

    /// Test that autocompletion for values of known type picks up nested
    /// values.
    #[test]
    fn test_autocomplete_value_filter() {
        let world = TestWorld::new("#import \"design.typ\": clrs; #rect(fill: )")
            .with_source(
                "design.typ",
                "#let clrs = (a: red, b: blue); #let nums = (a: 1, b: 2)",
            );

        test(&world, -2)
            .must_include(["clrs", "aqua"])
            .must_exclude(["nums", "a", "b"]);
    }

    #[test]
    fn test_autocomplete_packages() {
        test("#import \"@\"", -2).must_include([q!("@preview/example:0.1.0")]);
    }

    #[test]
    fn test_autocomplete_file_path() {
        let world = TestWorld::new("#include \"\"")
            .with_source("utils.typ", "")
            .with_source("content/a.typ", "#image()")
            .with_source("content/b.typ", "#csv(\"\")")
            .with_source("content/c.typ", "#include \"\"")
            .with_source("content/d.typ", "#pdf.attach(\"\")")
            .with_source("content/e.typ", "#math.attach(\"\")")
            .with_source("content/f.typ", "#read(\"\")")
            .with_asset_at("assets/tiger.jpg", "tiger.jpg")
            .with_asset_at("assets/rhino.png", "rhino.png")
            .with_asset_at("data/example.csv", "example.csv");

        test(&world, -2)
            .must_include([q!("content/a.typ"), q!("content/b.typ"), q!("utils.typ")])
            .must_exclude([q!("assets/tiger.jpg")]);

        test(&world, ("content/a.typ", -2))
            .must_include([q!("../assets/tiger.jpg"), q!("../assets/rhino.png")])
            .must_exclude([q!("../data/example.csv"), q!("b.typ")]);

        test(&world, ("content/b.typ", -3)).must_include([q!("../data/example.csv")]);

        test(&world, ("content/c.typ", -2))
            .must_include([q!("../main.typ"), q!("a.typ"), q!("b.typ")])
            .must_exclude([q!("c.typ")]);

        test(&world, ("content/d.typ", -2))
            .must_include([q!("../assets/tiger.jpg"), q!("../data/example.csv")]);

        test(&world, ("content/e.typ", -2)).must_exclude([q!("../data/example.csv")]);

        test(&world, ("content/f.typ", -2))
            .must_include([
                q!("a.typ"),
                q!("../assets/tiger.jpg"),
                q!("../data/example.csv"),
            ])
            .must_exclude([q!("f.typ")]);
    }

    #[test]
    fn test_autocomplete_file_path_with_prefix() {
        let world = TestWorld::new("")
            .with_source("content/main.typ", "#read(\"a\")")
            .with_source("content/test1.typ", "#read(\"\")")
            .with_source("content/test2.typ", "#read(\"..\")")
            .with_source("content/test3.typ", "#read(\"../assets/r\")")
            .with_source("content/aux.typ", "")
            .with_asset_at("assets/tiger.jpg", "tiger.jpg")
            .with_asset_at("assets/rhino.png", "rhino.png");

        test(&world, ("content/main.typ", -3))
            .must_include([q!("aux.typ")])
            .must_exclude([q!("test.typ")]);

        test(&world, ("content/test1.typ", -3)).must_include([
            q!("aux.typ"),
            q!("../assets/tiger.jpg"),
            q!("../assets/tiger.jpg"),
        ]);

        test(&world, ("content/test2.typ", -3))
            .must_include([q!("../assets/rhino.png"), q!("../assets/tiger.jpg")])
            .must_exclude([q!("aux.typ")]);

        test(&world, ("content/test3.typ", -3))
            .must_include([q!("../assets/rhino.png")])
            .must_exclude([q!("aux.typ"), q!("../assets/tiger.jpg")]);
    }

    #[test]
    fn test_autocomplete_figure_snippets() {
        let res = test("#figure()", -2);
        res.at("image").must_apply_as("image(\"${}\"),");
        res.at("table").must_apply_as("table(\n  ${}\n),");

        test("#figure(cap)", -2).at("caption").must_apply_as("caption: [${}]");
    }

    #[test]
    fn test_autocomplete_import_items() {
        let world = TestWorld::new("#import \"other.typ\": ")
            .with_source("second.typ", "#import \"other.typ\": th")
            .with_source("other.typ", "#let this = 1; #let that = 2");

        test(&world, ("main.typ", 21))
            .must_include(["*", "this", "that"])
            .must_exclude(["figure"]);
        test(&world, ("second.typ", 23))
            .must_include(["this", "that"])
            .must_exclude(["*", "figure"]);
    }

    #[test]
    fn test_autocomplete_type_methods() {
        test("#\"hello\".", -1).must_include(["len", "contains"]);
        test("#table().", -1).must_exclude(["cell"]);
    }

    #[test]
    fn test_autocomplete_content_methods() {
        test("#show outline.entry: it => it.\n#outline()\n= Hi", 30)
            .must_include(["indented", "body", "page"]);
    }

    #[test]
    fn test_autocomplete_symbol_variants() {
        test("#sym.arrow.", -1)
            .must_include(["r", "dashed"])
            .must_exclude(["cases"]);
        test("$ arrow. $", -3)
            .must_include(["r", "dashed"])
            .must_exclude(["cases"]);
    }

    #[test]
    fn test_autocomplete_fonts() {
        test("#text(font:)", -2)
            .must_include([q!("Libertinus Serif"), q!("New Computer Modern Math")]);

        test("#show link: set text(font: )", -2)
            .must_include([q!("Libertinus Serif"), q!("New Computer Modern Math")]);

        test("#show math.equation: set text(font: )", -2)
            .must_include([q!("New Computer Modern Math")])
            .must_exclude([q!("Libertinus Serif")]);

        test("#show math.equation: it => { set text(font: )\nit }", -7)
            .must_include([q!("New Computer Modern Math")])
            .must_exclude([q!("Libertinus Serif")]);
    }

    #[test]
    fn test_autocomplete_typed_html() {
        test("#html.div(translate: )", -2)
            .must_include(["true", "false"])
            .must_exclude([q!("yes"), q!("no")]);
        test("#html.input(value: )", -2).must_include(["float", "string", "red", "blue"]);
        test("#html.div(role: )", -2).must_include([q!("alertdialog")]);
    }

    #[test]
    fn test_autocomplete_in_function_params_after_comma_and_colon() {
        let document = "#text(size: 12pt, [])";

        // After colon
        test(document, 11).must_include(["length"]);
        test_implicit(document, 11).must_include(["length"]);

        test(document, 12).must_include(["length"]);
        test_implicit(document, 12).must_include(["length"]);

        // After comma
        test(document, 17).must_include(["font"]);
        test_implicit(document, 17).must_be_empty();

        test(document, 18).must_include(["font"]);
        test_implicit(document, 18).must_include(["font"]);
    }

    #[test]
    fn test_autocomplete_in_list_literal() {
        let document = "#let val = 0\n#(1, \"one\")";

        // After opening paren
        test(document, 15).must_include(["color", "val"]);
        test_implicit(document, 15).must_be_empty();

        // After first element
        test(document, 16).must_be_empty();
        test_implicit(document, 16).must_be_empty();

        // After comma
        test(document, 17).must_include(["color", "val"]);
        test_implicit(document, 17).must_be_empty();

        test(document, 18).must_include(["color", "val"]);
        test_implicit(document, 18).must_be_empty();
    }

    #[test]
    fn test_autocomplete_in_dict_literal() {
        let document = "#let first = 0\n#(first: 1, second: one)";

        // After opening paren
        test(document, 17).must_be_empty();
        test_implicit(document, 17).must_be_empty();

        // After first key
        test(document, 22).must_be_empty();
        test_implicit(document, 22).must_be_empty();

        // After colon
        test(document, 23).must_include(["align", "first"]);
        test_implicit(document, 23).must_be_empty();

        test(document, 24).must_include(["align", "first"]);
        test_implicit(document, 24).must_be_empty();

        // After first value
        test(document, 25).must_be_empty();
        test_implicit(document, 25).must_be_empty();

        // After comma
        test(document, 26).must_be_empty();
        test_implicit(document, 26).must_be_empty();

        test(document, 27).must_be_empty();
        test_implicit(document, 27).must_be_empty();
    }

    #[test]
    fn test_autocomplete_in_destructuring() {
        let document = "#let value = 20\n#let (va: value) = (va: 10)";

        // At destructuring rename pattern source
        test(document, 24).must_be_empty();
        test_implicit(document, 24).must_be_empty();
    }

    #[test]
    fn test_autocomplete_user_function() {
        let world = TestWorld::new("#import \"lib.typ\"\n#lib.")
            .with_source("lib.typ", crate::tests::EXAMPLE_CLOSURE);
        let res = test(&world, -1);
        res.must_include(["foo"]);
        res.at("foo").must_have_detail("A useful function.");
    }

    #[test]
    fn test_autocomplete_user_function_params() {
        let world = TestWorld::new("#import \"lib.typ\": *\n#foo()")
            .with_source("lib.typ", crate::tests::EXAMPLE_CLOSURE);
        let res = test(&world, -2);
        res.must_include(["forest", "tree"]);
        res.at("forest").must_have_detail("More trees.");
        res.at("tree").must_have_detail("Tree with three slashes.");
    }
}

