11	/// Try to determine a set of possible values for an expression.
12	pub fn analyze_expr(
13	    world: &dyn IdeWorld,
14	    node: &LinkedNode,
15	) -> EcoVec<(Value, Option<Styles>)> {
16	    let Some(expr) = node.cast::<ast::Expr>() else {
17	        return eco_vec![];
18	    };
19	
20	    let val = match expr {
21	        ast::Expr::None(_) => Value::None,
22	        ast::Expr::Auto(_) => Value::Auto,
23	        ast::Expr::Bool(v) => Value::Bool(v.get()),
24	        ast::Expr::Int(v) if v.get().is_ok() => Value::Int(v.get().unwrap()),
25	        ast::Expr::Float(v) => Value::Float(v.get()),
26	        ast::Expr::Numeric(v) => Value::numeric(v.get()),
27	        ast::Expr::Str(v) => Value::Str(v.get().into()),
28	        _ => {
29	            if node.kind() == SyntaxKind::Contextual
30	                && let Some(child) = node.children().next_back()
31	            {
32	                return analyze_expr(world, &child);
33	            }
34	
35	            if let Some(parent) = node.parent()
36	                && matches!(
37	                    parent.kind(),
38	                    SyntaxKind::FieldAccess | SyntaxKind::MathFieldAccess
39	                )
40	                && node.index() > 0
41	            {
42	                return analyze_expr(world, parent);
43	            }
44	
45	            return typst::trace::<PagedDocument>(world.upcast(), node.span());
46	        }
47	    };
48	
49	    eco_vec![(val, None)]
50	}
51	
52	/// Tries to determine a single value for an expression with tracing, falling
53	/// back to a standard library definition, if applicable.
54	///
55	/// This gives us best-effort results in dead code.
56	pub fn analyze_expr_with_fallback(
57	    world: &dyn IdeWorld,
58	    node: &LinkedNode,
59	) -> Option<Value> {
60	    if let Some((value, _)) = analyze_expr(world, node).into_iter().next() {
61	        return Some(value);
62	    }
63	
64	    let globals = crate::utils::globals(world, node);
65	    let guard = world.silent_binding_guard();
66	    let value = match node.cast::<ast::Expr>()? {
67	        ast::Expr::Ident(ident) => globals.get(&ident)?.read(&guard).ok()?,
68	        ast::Expr::FieldAccess(access) => match access.target() {
69	            ast::Expr::Ident(target) => globals
70	                .get(&target)?
71	                .read(&guard)
72	                .ok()?
73	                .scope()?
74	                .get(&access.field())?
75	                .read(&guard)
76	                .ok()?,
77	            _ => return None,
78	        },
79	        _ => return None,
80	    };
81	
82	    Some(value.clone())
83	}
84	
85	/// Tries to load a module from the given `source` node.
86	pub fn analyze_import(world: &dyn IdeWorld, source: &LinkedNode) -> Option<Value> {
87	    // Use span in the node for resolving imports with relative paths.
88	    let source_span = source.span();
89	    let (source, _) = analyze_expr(world, source).into_iter().next()?;
90	    if source.scope().is_some() {
91	        return Some(source);
92	    }
93	
94	    let Value::Str(path) = source else { return None };
95	
96	    crate::utils::with_engine(world, |engine| {
97	        typst_eval::import(engine, &path, source_span).ok().map(Value::Module)
98	    })
99	}
100	
101	/// Find all labels and details for them.
102	///
103	/// Returns:
104	/// - All labels and descriptions for them, if available
105	/// - A split offset: All labels before this offset belong to nodes, all after
106	///   belong to a bibliography.
107	///
108	/// Note: When multiple labels in the document have the same identifier,
109	/// this only returns the first one.
110	pub fn analyze_labels(output: impl AsOutput) -> (Vec<(Label, Option<EcoString>)>, usize) {
111	    let introspector = output.as_output().introspector();
112	
113	    let mut output = vec![];
114	    let mut seen_labels = FxHashSet::default();
115	
116	    // Labels in the document.
117	    for elem in introspector.query_labelled() {
118	        let Some(label) = elem.label() else { continue };
119	        if !seen_labels.insert(label) {
120	            continue;
121	        }
122	
123	        let details = elem
124	            .to_packed::<FigureElem>()
125	            .and_then(|figure| match figure.caption.as_option() {
126	                Some(Some(caption)) => Some(caption.pack_ref()),
127	                _ => None,
128	            })
129	            .unwrap_or(&elem)
130	            .get_by_name("body")
131	            .ok()
132	            .and_then(|field| match field {
133	                Value::Content(content) => Some(content),
134	                _ => None,
135	            })
136	            .as_ref()
137	            .unwrap_or(&elem)
138	            .plain_text();
139	        output.push((label, Some(details)));
140	    }
141	
142	    let split = output.len();
143	
144	    // Bibliography keys.
145	    output.extend(BibliographyElem::keys(introspector.track()));
146	
147	    (output, split)
148	}
