184	/// Checks whether the given value or any of its constituent parts satisfy the
185	/// predicate.
186	pub fn check_value_recursively(
187	    guard: &SilentBindingGuard,
188	    value: &Value,
189	    predicate: impl Fn(&Value) -> bool,
190	) -> bool {
191	    let mut searcher = Searcher { guard, steps: 0, predicate, max_steps: 1000 };
192	    match searcher.find(value) {
193	        ControlFlow::Break(matching) => matching,
194	        ControlFlow::Continue(()) => false,
195	    }
196	}
197	
198	/// Recursively searches for a value that passes the filter, but without
199	/// exceeding a maximum number of search steps.
200	struct Searcher<'a, F> {
201	    guard: &'a SilentBindingGuard,
202	    max_steps: usize,
203	    steps: usize,
204	    predicate: F,
205	}
206	
207	impl<F> Searcher<'_, F>
208	where
209	    F: Fn(&Value) -> bool,
210	{
211	    fn find(&mut self, value: &Value) -> ControlFlow<bool> {
212	        if (self.predicate)(value) {
213	            return ControlFlow::Break(true);
214	        }
215	
216	        if self.steps > self.max_steps {
217	            return ControlFlow::Break(false);
218	        }
219	
220	        self.steps += 1;
221	
222	        match value {
223	            Value::Dict(dict) => {
224	                self.find_iter(dict.iter().map(|(_, v)| v))?;
225	            }
226	            Value::Content(content) => {
227	                self.find_iter(content.fields().iter().map(|(_, v)| v))?;
228	            }
229	            Value::Module(module) => {
230	                let guard = self.guard;
231	                self.find_iter(
232	                    module
233	                        .scope()
234	                        .iter()
235	                        .filter_map(move |(_name, binding)| binding.read(guard).ok()),
236	                )?;
237	            }
238	            _ => {}
239	        }
240	
241	        ControlFlow::Continue(())
242	    }
243	
244	    fn find_iter<'a>(
245	        &mut self,
246	        iter: impl Iterator<Item = &'a Value>,
247	    ) -> ControlFlow<bool> {
248	        for item in iter {
249	            self.find(item)?;
250	        }
251	        ControlFlow::Continue(())
252	    }
253	}
