19	/// Describe the item under the cursor.
20	///
21	/// Passing a `document` (from a previous compilation) is optional, but enhances
22	/// the tooltips. Label tooltips, for instance, are only generated when the
23	/// document is available.
24	pub fn tooltip(
25	    world: &dyn IdeWorld,
26	    output: Option<impl AsOutput>,
27	    source: &Source,
28	    cursor: usize,
29	    side: Side,
30	) -> Option<Tooltip> {
31	    let leaf = LinkedNode::new(source.root()).leaf_at(cursor, side)?;
32	    if leaf.kind().is_trivia() {
33	        return None;
34	    }
35	
36	    named_param_tooltip(world, &leaf)
37	        .or_else(|| font_tooltip(world, &leaf))
38	        .or_else(|| label_tooltip(output?, &leaf))
39	        .or_else(|| import_tooltip(world, &leaf))
40	        .or_else(|| expr_tooltip(world, &leaf))
41	        .or_else(|| closure_tooltip(&leaf))
42	}
