961	/// A syntax node in a context.
962	///
963	/// Knows its exact offset in the file and provides access to its
964	/// children, parent and siblings.
965	///
966	/// **Note that all sibling and leaf accessors skip over trivia!**
967	#[derive(Clone)]
968	pub struct LinkedNode<'a> {
969	    /// The underlying syntax node.
970	    node: &'a SyntaxNode,
971	    /// The parent of this node.
972	    parent: Option<Rc<Self>>,
973	    /// The index of this node in its parent's children array.
974	    index: usize,
975	    /// This node's byte offset in the source file.
976	    offset: usize,
977	}
978	
979	impl<'a> LinkedNode<'a> {
980	    /// Start a new traversal at a root node.
981	    pub fn new(root: &'a SyntaxNode) -> Self {
982	        Self { node: root, parent: None, index: 0, offset: 0 }
983	    }
984	
985	    /// Get the contained syntax node.
986	    pub fn get(&self) -> &'a SyntaxNode {
987	        self.node
988	    }
989	
990	    /// The index of this node in its parent's children list.
991	    pub fn index(&self) -> usize {
992	        self.index
993	    }
994	
995	    /// The absolute byte offset of this node in the source file.
996	    pub fn offset(&self) -> usize {
997	        self.offset
998	    }
999	
1000	    /// The byte range of this node in the source file.
1001	    pub fn range(&self) -> Range<usize> {
1002	        self.offset..self.offset + self.node.len()
1003	    }
1004	
1005	    /// An iterator over this node's children.
1006	    pub fn children(&self) -> LinkedChildren<'a> {
1007	        LinkedChildren {
1008	            parent: Rc::new(self.clone()),
1009	            iter: self.node.children().enumerate(),
1010	            front: self.offset,
1011	            back: self.offset + self.len(),
1012	        }
1013	    }
1014	
1015	    /// Find a descendant with the given span.
1016	    pub fn find(&self, span: Span) -> Option<Self> {
1017	        match span.get() {
1018	            SpanKind::Detached => None,
1019	            SpanKind::Number { id: _, num } => self.find_number(num),
1020	            SpanKind::Range { id: _, range } => self.find_range(range.start, range.end),
1021	        }
1022	    }
1023	
1024	    /// Find the descendant whose span number matches the given number.
1025	    ///
1026	    /// This relies on the ordering guarantees of numbered spans:
1027	    /// - The number of a parent is smaller than the numbers of all its children
1028	    /// - The numbers of sibling nodes always increase from left to right
1029	    pub(crate) fn find_number(&self, target: SpanNumber) -> Option<Self> {
1030	        let number = self.span().number();
1031	        if number == target.0 {
1032	            return Some(self.clone());
1033	        }
1034	
1035	        // The parent of a subtree has a smaller span number than all of its
1036	        // descendants. Therefore, we can bail out early if the target span's
1037	        // number is smaller than our number.
1038	        if self.node.is_inner() && number < target.0 {
1039	            // Use `self.children()`, not `inner.children()` to preserve being
1040	            // in a `LinkedNode`.
1041	            let mut children = self.children().peekable();
1042	            while let Some(child) = children.next() {
1043	                // Every node in this child's subtree has a smaller span number than
1044	                // the next sibling. Therefore we only need to recurse if the next
1045	                // sibling's span number is larger than the target span's number.
1046	                if children.peek().is_none_or(|next| next.span().number() > target.0)
1047	                    && let Some(found) = child.find_number(target)
1048	                {
1049	                    return Some(found);
1050	                }
1051	            }
1052	        }
1053	
1054	        None
1055	    }
1056	
1057	    /// Find the descendant whose byte range matches the given range exactly.
1058	    pub(crate) fn find_range(&self, start: usize, end: usize) -> Option<Self> {
1059	        if start == self.offset && end == self.offset + self.len() {
1060	            return Some(self.clone());
1061	        }
1062	        for child in self.children() {
1063	            // Descend into the single child which fully covers the range.
1064	            if child.offset <= start && end <= child.offset + child.len() {
1065	                return child.find_range(start, end);
1066	            }
1067	        }
1068	        None
1069	    }
1070	
1071	    /// Get the [`SyntaxMode`] we will be in when immediately after this node.
1072	    ///
1073	    /// Unlike some other `LinkedNode` methods, this does not treat all trivia
1074	    /// the same: it returns `None` for both comments and the bodies of raw text
1075	    /// and returns `Some` for whitespace (based on the parent's mode). The only
1076	    /// other way this would return `None` is when inside a partial tree, i.e.
1077	    /// one not rooted in `Markup`, `Math`, or `Code`.
1078	    ///
1079	    /// Also note that errors inherit the mode of their parent.
1080	    pub fn mode_after(&self) -> Option<SyntaxMode> {
1081	        match self.kind().mode_after() {
1082	            ModeAfter::Known(mode) => Some(mode),
1083	            // Comments and the bodies of raw text have no mode.
1084	            ModeAfter::None => None,
